// Kotlin: a value class is a plain long at runtime, unless it has to be boxed
@JvmInline
value class FileSize(val bytes: Long) {
    operator fun plus(other: FileSize) = FileSize(bytes + other.bytes)       // compiles to long + long
}

var total = FileSize(0)
for (s in sizes) total += FileSize(s)                                        // no objects

